{"command": "cd /workspace && cat > src/cli.rs <<'EOF'
use clap::builder::PossibleValue;
use clap::{Arg, ArgAction, Command};

pub const VERSION: &str = "0.6.5";
pub const ABOUT: &str = "\u{1f381} generate beautiful landing pages for your projects";

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum OutputFormat {
    Human,
    Json,
}

impl OutputFormat {
    pub fn as_str(&self) -> &'static str {
        match self {
            OutputFormat::Human => "human",
            OutputFormat::Json => "json",
        }
    }
}

fn output_format_arg() -> Arg {
    Arg::new("output-format")
        .long("output-format")
        .value_name("OUTPUT_FORMAT")
        .help("The format of the output")
        .default_value("human")
        .value_parser(clap::builder::PossibleValuesParser::new([
            PossibleValue::new("human").help("Human-readable output"),
            PossibleValue::new("json").help("Machine-readable JSON output"),
        ]))
        .help_heading("GLOBAL OPTIONS")
        .global(true)
}

fn verbose_arg() -> Arg {
    Arg::new("verbose")
        .long("verbose")
        .short('v')
        .action(ArgAction::SetTrue)
        .help("Whether to output more detailed debug information")
        .help_heading("GLOBAL OPTIONS")
        .global(true)
}

pub fn build_cli() -> Command {
    let build = Command::new("build").about("Build an oranda site").arg(
        Arg::new("json-only")
            .long("json-only")
            .action(ArgAction::SetTrue)
            .help("Only build the artifacts JSON file (if applicable) and other files that may be used to support it, such as installer source files"),
    );

    let dev = Command::new("dev")
        .about("Start a local development server that recompiles your oranda site if a file changes")
        .arg(
            Arg::new("port")
                .long("port")
                .value_name("PORT")
                .value_parser(clap::value_parser!(u16))
                .help("The port for the file server to be launched on"),
        )
        .arg(
            Arg::new("no-first-build")
                .long("no-first-build")
                .action(ArgAction::SetTrue)
                .help("Skip the first build before starting to watch for changes"),
        )
        .arg(
            Arg::new("include-paths")
                .long("include-paths")
                .short('i')
                .value_name("INCLUDE_PATHS")
                .action(ArgAction::Append)
                .help("List of extra paths to watch"),
        );

    let serve = Command::new("serve")
        .about("Start a file server to access your oranda site in a browser")
        .arg(
            Arg::new("port")
                .long("port")
                .value_name("PORT")
                .value_parser(clap::value_parser!(u16))
                .default_value("7979"),
        );

    let ci = Command::new("ci")
        .about("Generates a CI file that can be used to deploy your site")
        .arg(
            Arg::new("ci")
                .long("ci")
                .value_name("CI")
                .default_value("github")
                .value_parser(clap::builder::PossibleValuesParser::new([
                    PossibleValue::new("github").help("Deploy to GitHub Pages using GitHub Actions"),
                ]))
                .help("What CI to generate a file for"),
        );

    let generate = Command::new("generate")
        .about("Generate infrastructure files for oranda sites")
        .arg(
            Arg::new("output-path")
                .long("output-path")
                .short('o')
                .value_name("OUTPUT_PATH")
                .help("Path to the output file"),
        )
        .arg(
            Arg::new("site-path")
                .long("site-path")
                .short('s')
                .value_name("SITE_PATH")
                .help("Path to your oranda site"),
        )
        .subcommand(ci);

    Command::new("oranda")
        .version(VERSION)
        .about(ABOUT)
        .args([verbose_arg(), output_format_arg()])
        .subcommands([build, dev, serve, generate])
        .arg_required_else_help(true)
}
EOF
cargo build --offline --release 2>&1|tail -2; B=target/release/oranda; for c in "" build dev serve generate "generate ci"; do n=$(echo ${c:-main}|tr ' ' '_'); (exec -a executable $B $c --help > /tmp/mine_hl_$n.txt 2>&1); (exec -a executable $B $c -h > /tmp/mine_hs_$n.txt 2>&1); diff /tmp/hl_$n.txt /tmp/mine_hl_$n.txt >/dev/null && echo "LONG $n OK" || { echo "LONG $n DIFF"; diff /tmp/hl_$n.txt /tmp/mine_hl_$n.txt|head -10; }; diff /tmp/hs_$n.txt /tmp/mine_hs_$n.txt >/dev/null && echo "SHORT $n OK" || { echo "SHORT $n DIFF"; diff /tmp/hs_$n.txt /tmp/mine_hs_$n.txt|head -10; }; done"}

