cat > vendor/terminal_size/src/lib.rs <<'EOF'
//! A tiny re-implementation of the `terminal_size` crate's public API, used so
//! that `clap`'s `wrap_help` feature can be compiled without network access.

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Width(pub u16);

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Height(pub u16);

#[repr(C)]
#[derive(Default)]
struct Winsize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

const TIOCGWINSZ: libc_ulong = 0x5413;
#[allow(non_camel_case_types)]
type libc_ulong = std::os::raw::c_ulong;

extern "C" {
    fn ioctl(fd: std::os::raw::c_int, request: libc_ulong, ...) -> std::os::raw::c_int;
}

/// Returns the size of the terminal attached to stdout.
pub fn terminal_size() -> Option<(Width, Height)> {
    terminal_size_of(unsafe { std::os::fd::BorrowedFd::borrow_raw(1) })
}

/// Returns the size of the terminal the given file descriptor points to.
pub fn terminal_size_of(fd: std::os::fd::BorrowedFd) -> Option<(Width, Height)> {
    let mut winsize = Winsize::default();
    let result = unsafe { ioctl(fd.as_raw_fd(), TIOCGWINSZ, &mut winsize as *mut Winsize) };
    if result == -1 {
        return None;
    }
    if winsize.ws_col == 0 && winsize.ws_row == 0 {
        return None;
    }
    Some((Width(winsize.ws_col), Height(winsize.ws_row)))
}

/// Returns the size of the terminal attached to stderr.
pub fn terminal_size_of_stderr() -> Option<(Width, Height)> {
    terminal_size_of(unsafe { std::os::fd::BorrowedFd::borrow_raw(2) })
}
EOF
sed -i 's/^clap = "4.6.1"$/clap = { version = "4.6.1", features = ["wrap_help"] }/' Cargo.toml && sed -i 's/^serde_json = "1.0.150"$/serde_json = "1.0.150"\nterminal_size = { path = "vendor\/terminal_size" }/' Cargo.toml && cat Cargo.toml | tail -12"}

