//! Diagnostics that mirror the `miette` graphical report handler output used by
//! the original program.

pub const TERM_WIDTH: usize = 118;

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Severity {
    Error,
    Warning,
}

impl Severity {
    pub fn as_str(&self) -> &'static str {
        match self {
            Severity::Error => "error",
            Severity::Warning => "warning",
        }
    }

    fn icon(&self) -> char {
        match self {
            Severity::Error => '\u{00d7}',
            Severity::Warning => '\u{26a0}',
        }
    }
}

#[derive(Clone, Debug)]
pub struct Label {
    pub offset: usize,
    pub length: usize,
}

#[derive(Clone, Debug)]
pub struct Diagnostic {
    pub severity: Severity,
    pub message: String,
    pub causes: Vec<String>,
    pub help: Option<String>,
    pub filename: Option<String>,
    pub labels: Vec<Label>,
}

impl Diagnostic {
    pub fn error(message: impl Into<String>) -> Self {
        Diagnostic {
            severity: Severity::Error,
            message: message.into(),
            causes: Vec::new(),
            help: None,
            filename: None,
            labels: Vec::new(),
        }
    }

    pub fn warning(message: impl Into<String>) -> Self {
        Diagnostic {
            severity: Severity::Warning,
            message: message.into(),
            causes: Vec::new(),
            help: None,
            filename: None,
            labels: Vec::new(),
        }
    }

    pub fn with_causes(mut self, causes: Vec<String>) -> Self {
        self.causes = causes;
        self
    }

    pub fn with_help(mut self, help: impl Into<String>) -> Self {
        self.help = Some(help.into());
        self
    }

    /// Render the human readable (graphical) form of this diagnostic.
    pub fn render_human(&self) -> String {
        let mut out = String::new();
        let icon = self.severity.icon();
        let first = format!("  {icon} ");
        out.push_str(&block(&self.message, TERM_WIDTH - first.len(), &first, "  \u{2502} "));

        let total = self.causes.len();
        for (idx, cause) in self.causes.iter().enumerate() {
            let last = idx + 1 == total;
            let (first_p, cont_p) = if last {
                ("  \u{2570}\u{2500}\u{25b6} ", "      ")
            } else {
                ("  \u{251c}\u{2500}\u{25b6} ", "  \u{2502}   ")
            };
            out.push_str(&block(cause, TERM_WIDTH - first_p.len(), first_p, cont_p));
        }

        if let Some(help) = &self.help {
            out.push_str(&block(
                help,
                TERM_WIDTH - "  help: ".len(),
                "  help: ",
                "      ",
            ));
        }

        if !self.labels.is_empty() {
            if let Some(filename) = &self.filename {
                out.push_str(&render_snippet(filename, &self.labels));
            }
        }

        out.push('\n');
        out
    }

    /// Render the machine readable (JSON) form of this diagnostic.
    pub fn render_json(&self) -> String {
        let mut out = String::from("{\"diagnostic\": {");
        out.push_str(&format!(
            "\"message\": {},\"severity\": {},\"causes\": [",
            json_str(&self.message),
            json_str(self.severity.as_str())
        ));
        for (idx, cause) in self.causes.iter().enumerate() {
            if idx != 0 {
                out.push(',');
            }
            out.push_str(&json_str(cause));
        }
        out.push(']');
        if let Some(help) = &self.help {
            out.push_str(&format!(",\"help\": {}", json_str(help)));
        }
        if let Some(filename) = &self.filename {
            out.push_str(&format!(",\"filename\": {}", json_str(filename)));
        }
        out.push_str(",\"labels\": [");
        for (idx, label) in self.labels.iter().enumerate() {
            if idx != 0 {
                out.push(',');
            }
            out.push_str(&format!(
                "{{\"span\": {{\"offset\": {},\"length\": {}}}}}",
                label.offset, label.length
            ));
        }
        out.push_str("],\"related\": []}}");
        out
    }
}

/// Escape a string as a JSON string literal (compact, serde_json compatible).
pub fn json_str(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0c}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn display_width(s: &str) -> usize {
    s.chars().count()
}

/// Greedy word wrapping, matching `textwrap`'s behaviour with long words broken.
fn wrap_line(line: &str, width: usize) -> Vec<String> {
    if width == 0 {
        return vec![line.to_string()];
    }
    if line.is_empty() {
        return vec![String::new()];
    }
    // Tokenise into runs of whitespace / non-whitespace so that we can both
    // preserve whitespace and break long words.
    let mut tokens: Vec<&str> = Vec::new();
    let bytes = line.as_bytes();
    let mut start = 0usize;
    let mut idx = 0usize;
    while idx < bytes.len() {
        let ws = bytes[idx].is_ascii_whitespace();
        let mut j = idx;
        while j < bytes.len() && bytes[j].is_ascii_whitespace() == ws {
            j += 1;
        }
        tokens.push(&line[start..j]);
        start = j;
        idx = j;
    }

    let mut out: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut cur_len = 0usize;

    for tok in tokens {
        let tl = display_width(tok);
        if cur_len + tl <= width {
            cur.push_str(tok);
            cur_len += tl;
        } else if cur_len == 0 {
            if tl > width {
                // Break the long token into chunks.
                let mut rest = tok;
                let mut first = true;
                while display_width(rest) > width {
                    let mut take = 0usize;
                    let mut it = rest.char_indices();
                    while let Some((b, c)) = it.next() {
                        if take + 1 > width {
                            break;
                        }
                        take += 1;
                        let _ = b;
                        let _ = c;
                    }
                    // take is the number of chars we can emit
                    let split = rest
                        .char_indices()
                        .nth(width)
                        .map(|(b, _)| b)
                        .unwrap_or(rest.len());
                    let (chunk, remainder) = rest.split_at(split);
                    if first {
                        cur.push_str(chunk);
                        first = false;
                    } else {
                        out.push(cur.clone());
                        cur = chunk.to_string();
                    }
                    cur_len = display_width(chunk);
                    rest = remainder;
                }
                if first {
                    cur.push_str(rest);
                    cur_len = display_width(rest);
                } else {
                    cur = rest.to_string();
                    cur_len = display_width(rest);
                }
            } else {
                cur.push_str(tok);
                cur_len += tl;
            }
        } else {
            // Flush the current line and start a new one
            out.push(cur.trim_end().to_string());
            cur = String::new();
            cur_len = 0;
            if tok.chars().all(|c| c.is_whitespace()) {
                // Whitespace at a line break is dropped
                continue;
            }
            if tl > width {
                let mut rest = tok;
                loop {
                    if display_width(rest) <= width {
                        cur.push_str(rest);
                        cur_len = display_width(rest);
                        break;
                    }
                    let split = rest
                        .char_indices()
                        .nth(width)
                        .map(|(b, _)| b)
                        .unwrap_or(rest.len());
                    let (chunk, remainder) = rest.split_at(split);
                    out.push(cur.clone());
                    cur = chunk.to_string();
                    cur_len = display_width(chunk);
                    rest = remainder;
                }
            } else {
                cur.push_str(tok);
                cur_len += tl;
            }
        }
    }

    out.push(cur.trim_end().to_string());
    out
}

/// Render a block of text with a prefix on the first line and a different
/// prefix on every continuation line.
fn block(text: &str, width: usize, first: &str, cont: &str) -> String {
    let lines = wrap_text(text, width);
    let mut out = String::new();
    for (idx, line) in lines.iter().enumerate() {
        if idx == 0 {
            out.push_str(first);
        } else {
            out.push_str(cont);
        }
        out.push_str(line);
        out.push('\n');
    }
    out
}

fn wrap_text(text: &str, width: usize) -> Vec<String> {
    let mut out = Vec::new();
    for line in text.split('\n') {
        out.extend(wrap_line(line, width));
    }
    out
}

/// Render the source snippet portion of a diagnostic.
fn render_snippet(filename: &str, labels: &[Label]) -> String {
    let mut out = String::new();
    // The source is provided via the attached source; we only ever render
    // snippets for files we have read.
    if let Some(src) = SNIPPET_SOURCE.get() {
        out.push_str(&render_snippet_from_source(filename, labels, src));
    }
    out
}

thread_local! {
    static SNIPPET_SOURCE: std::cell::RefCell<Option<String>> =
        const { std::cell::RefCell::new(None) };
}

/// Attach the source text that snippets should be rendered from.
pub fn set_snippet_source(src: Option<String>) {
    SNIPPET_SOURCE.with(|cell| *cell.borrow_mut() = src);
}

fn render_snippet_from_source(filename: &str, labels: &[Label], src: &str) -> String {
    let mut out = String::new();
    let lines: Vec<&str> = src.split('\n').collect();
    // Compute the line start offsets so that we can map offsets -> (line, col)
    let mut line_starts = vec![0usize];
    for (idx, line) in lines.iter().enumerate() {
        if idx + 1 < lines.len() {
            let start = line_starts[idx] + line.len() + 1;
            line_starts.push(start);
        }
    }
    let mut wanted: Vec<usize> = Vec::new();
    for label in labels {
        let offset = label.offset;
        // find the line containing the offset
        let mut line_no = 0usize;
        for (idx, start) in line_starts.iter().enumerate() {
            if *start <= offset {
                line_no = idx;
            } else {
                break;
            }
        }
        if lines.is_empty() {
            line_no = 0;
        }
        for extra in [line_no.saturating_sub(1), line_no, line_no + 1] {
            if extra < lines.len() && !wanted.contains(&extra) {
                wanted.push(extra);
            }
        }
    }
    if wanted.is_empty() {
        return out;
    }
    wanted.sort();

    let digits = wanted
        .iter()
        .map(|l| (l + 1).to_string().len())
        .max()
        .unwrap_or(1);
    let gutter_pad = digits + 2;
    let first_line_no = wanted[0] + 1;

    out.push_str(&format!(
        "{}\u{250d}\u{2500}[{}:{}:1]\n",
        " ".repeat(gutter_pad),
        filename,
        first_line_no
    ));
    for line_idx in wanted {
        let num = (line_idx + 1).to_string();
        let num_field = format!("{:>width$}", num, width = digits);
        out.push_str(&format!(" {} \u{2502} {}\n", num_field, lines[line_idx]));
        let has_label = labels.iter().any(|l| {
            let offset = l.offset;
            offset >= line_starts[line_idx]
                && offset < line_starts[line_idx] + lines[line_idx].len()
        });
        if has_label {
            let mut ul = String::new();
            ul.push_str(&" ".repeat(gutter_pad));
            ul.push('\u{00b7}');
            for label in labels {
                let offset = label.offset;
                if offset >= line_starts[line_idx]
                    && offset < line_starts[line_idx] + lines[line_idx].len()
                {
                    let col = offset - line_starts[line_idx];
                    ul.push_str(&" ".repeat(col));
                    ul.push_str(&"\u{2500}".repeat(label.length.max(1)));
                }
            }
            out.push_str(&ul);
            out.push('\n');
        }
    }
    out.push_str(&format!(
        "{}\u{2570}\u{2500}\u{2500}\u{2500}\u{2500}\n",
        " ".repeat(gutter_pad)
    ));
    out
}
RSEOF
