        " ".repeat(gutter_pad),
        filename,
        first_line_no
    ));
    for line_idx in wanted {
        let num = (line_idx + 1).to_string();
        let num_field = format!("{:>width$}", num, width = digits);
        out.push_str(&format!(" {} \u{2502} {}\n", num_field, lines[line_idx]));
        let has_label = labels.iter().any(|l| {
            let offset = l.offset;
            offset >= line_starts[line_idx]
                && offset < line_starts[line_idx] + lines[line_idx].len()
        });
        if has_label {
            let mut ul = String::new();
            ul.push_str(&" ".repeat(gutter_pad));
            ul.push('\u{00b7}');
            for label in labels {
                let offset = label.offset;
