    pub project: ProjectLayer,
    pub build: BuildLayer,
    pub marketing: MarketingLayer,
    pub styles: StyleLayer,
    pub components: ComponentLayer,
    pub workspace: WorkspaceLayer,
    pub dist_dir: String,
    pub path_prefix: Option<String>,
}

pub const DEFAULT_DIST_DIR: &str = "public";
pub const DEFAULT_README: &str = "README.md";
pub const DEFAULT_CSS_VERSION: &str = "v0.6.1";

impl Config {
    pub fn from_layer(layer: OrandaLayer) -> Config {
        let dist_dir = layer
            .build
            .as_ref()
            .and_then(|b| b.dist_dir.clone())
            .unwrap_or_else(|| DEFAULT_DIST_DIR.to_string());
        Config {
            project: layer.project.unwrap_or_default(),
            build: layer.build.unwrap_or_default(),
            marketing: layer.marketing.unwrap_or_default(),
            styles: layer.styles.unwrap_or_default(),
            components: layer.components.unwrap_or_default(),
            workspace: layer.workspace.unwrap_or_default(),
            dist_dir,
            path_prefix: layer
                .build
                .as_ref()
                .and_then(|b| b.path_prefix.clone()),
        }
    }

    pub fn readme_path(&self) -> String {
        self.project
            .readme_path
            .clone()
            .unwrap_or_else(|| DEFAULT_README.to_string())
    }
}
