//! Logging helpers that mimic oranda's `axo` logging style.

use crate::cli::OutputFormat;
use crate::diag::Diagnostic;

fn emit(msg: &str) {
    println!("{}", msg);
}

pub fn debug(msg: &str) {
    emit(&format!("\u{21aa} >o_o< DEBUG: {}", msg));
}

pub fn info(msg: &str) {
    emit(&format!("\u{21aa} >o_o< INFO: {}", msg));
}

pub fn success(msg: &str) {
    emit(&format!("\u{2713} >o_o< SUCCESS: {}", msg));
}

/// Print a diagnostic in the configured output format.
pub fn print_diagnostic(diag: &Diagnostic, format: OutputFormat) {
    match format {
        OutputFormat::Json => println!("{}", diag.render_json()),
        OutputFormat::Human => eprint!("{}", diag.render_human()),
    }
}

/// Warnings are always rendered in the human format, on stderr.
pub fn print_warning(diag: &Diagnostic) {
    eprint!("{}", diag.render_human());
}
RSEOF
echo ok"}

