            .build
            .as_ref()
            .and_then(|b| b.dist_dir.clone())
            .unwrap_or_else(|| DEFAULT_DIST_DIR.to_string());
        Config {
            project: layer.project.unwrap_or_default(),
            build: layer.build.unwrap_or_default(),
