//! A very small HTTP(S) client, only used to fetch oranda's own assets.
//!
//! The TLS layer is provided by the system OpenSSL, since no TLS crate is
//! available in the build environment.

#[link(name = "ssl")]
extern "C" {
    fn OPENSSL_init_ssl(opts: u64, settings: *const u8) -> i32;
    fn TLS_client_method() -> *const u8;
    fn SSL_CTX_new(method: *const u8) -> *mut u8;
    fn SSL_CTX_set_verify(ctx: *mut u8, mode: i32, cb: *const u8);
    fn SSL_new(ctx: *mut u8) -> *mut u8;
    fn SSL_set_fd(ssl: *mut u8, fd: i32) -> i32;
    fn SSL_connect(ssl: *mut u8) -> i32;
    fn SSL_write(ssl: *mut u8, buf: *const u8, len: i32) -> i32;
    fn SSL_read(ssl: *mut u8, buf: *mut u8, len: i32) -> i32;
    fn SSL_free(ssl: *mut u8);
    fn SSL_CTX_free(ctx: *mut u8);
}

#[link(name = "crypto")]
extern "C" {}

const OPENSSL_INIT_LOAD_SSL_STRINGS: u64 = 0x2;
const SSL_VERIFY_NONE: i32 = 0;

#[derive(Debug, Clone)]
pub struct Url {
    pub scheme: String,
    pub host: String,
    pub port: u16,
    pub path: String,
}

impl Url {
    pub fn parse(s: &str) -> Option<Url> {
        let (scheme, rest) = s.split_once("://")?;
        let (authority, path) = match rest.find('/') {
            Some(idx) => (&rest[..idx], &rest[idx..]),
            None => (rest, "/"),
        };
        let (host, port) = match authority.rsplit_once(':') {
            Some((h, p)) if p.chars().all(|c| c.is_ascii_digit()) && !p.is_empty() => {
                (h.to_string(), p.parse::<u16>().ok()?)
            }
            _ => (
                authority.to_string(),
                match scheme {
                    "https" => 443,
                    _ => 80,
                },
            ),
        };
        Some(Url {
            scheme: scheme.to_string(),
            host,
            port,
            path: path.to_string(),
        })
    }

    pub fn as_str(&self) -> String {
        let default_port = match self.scheme.as_str() {
            "https" => 443,
            _ => 80,
        };
        if self.port == default_port {
            format!("{}://{}{}", self.scheme, self.host, self.path)
        } else {
            format!("{}://{}:{}{}", self.scheme, self.host, self.port, self.path)
        }
    }
}

/// An error that mirrors the `reqwest` error chain we need to reproduce.
#[derive(Debug, Clone)]
pub enum FetchError {
    /// DNS resolution failed.
    Dns(String),
    /// TCP connection failed.
    Tcp(String),
    /// TLS handshake failed.
    Tls(String),
    /// Any other failure while talking to the server.
    Io(String),
}

impl FetchError {
    /// The display of the innermost error.
    fn inner(&self) -> String {
        match self {
            FetchError::Dns(e) => format!("failed to lookup address information: {}", e),
            FetchError::Tcp(e) => e.clone(),
            FetchError::Tls(e) => e.clone(),
            FetchError::Io(e) => e.clone(),
        }
    }

    fn middle(&self) -> String {
        match self {
            FetchError::Dns(e) => format!("dns error: failed to lookup address information: {}", e),
            FetchError::Tcp(e) => format!("tcp connect error: {}", e),
            FetchError::Tls(e) => format!("invalid peer certificate: {}", e),
            FetchError::Io(e) => format!("error reading a body from connection: {}", e),
        }
    }

    /// Display of the `hyper` level error.
    fn outer(&self) -> String {
        format!("error trying to connect: {}", self.middle())
    }

    /// The full `reqwest` style display.
    pub fn display(&self, url: &str) -> String {
        format!("error sending request for url ({}): {}", url, self.outer())
    }

    /// The list of cause displays, innermost last.
    pub fn causes(&self) -> Vec<String> {
        vec![self.outer(), self.middle(), self.inner()]
    }
}

fn io_message(err: &std::io::Error) -> String {
    // Match the way `std` (and therefore hyper) renders OS errors.
    err.to_string()
}

/// Resolve a hostname, returning an error that looks like a DNS failure.
fn resolve(url: &Url) -> Result<Vec<std::net::SocketAddr>, FetchError> {
    let addr = format!("{}:{}", url.host, url.port);
    match addr.to_socket_addrs() {
        Ok(iter) => Ok(iter.collect()),
        Err(e) => Err(FetchError::Dns(dns_message(&e))),
    }
}

fn dns_message(err: &std::io::Error) -> String {
    let msg = err.to_string();
    // std renders getaddrinfo failures as
    // "failed to lookup address information: <strerror>"
    msg.strip_prefix("failed to lookup address information: ")
        .unwrap_or(&msg)
        .to_string()
}

struct Tls {
    ssl: *mut u8,
    ctx: *mut u8,
}

impl Tls {
    fn new() -> Option<Tls> {
        unsafe {
            OPENSSL_init_ssl(OPENSSL_INIT_LOAD_SSL_STRINGS, std::ptr::null());
            let method = TLS_client_method();
            if method.is_null() {
                return None;
            }
            let ctx = SSL_CTX_new(method);
            if ctx.is_null() {
                return None;
            }
            SSL_CTX_set_verify(ctx, SSL_VERIFY_NONE, std::ptr::null());
            let ssl = SSL_new(ctx);
            if ssl.is_null() {
                SSL_CTX_free(ctx);
                return None;
            }
            Some(Tls { ssl, ctx })
        }
    }
}

impl Drop for Tls {
    fn drop(&mut self) {
        unsafe {
            SSL_free(self.ssl);
            SSL_CTX_free(self.ctx);
        }
    }
}

/// Perform a GET request, returning the response body.
pub fn get(url: &str) -> Result<Vec<u8>, FetchError> {
    let parsed = Url::parse(url).ok_or_else(|| FetchError::Io("invalid url".to_string()))?;
    let addrs = resolve(&parsed)?;
    let mut last_err: Option<std::io::Error> = None;
    let mut stream: Option<std::net::TcpStream> = None;
    for addr in &addrs {
        match std::net::TcpStream::connect_timeout(addr, std::time::Duration::from_secs(30)) {
            Ok(s) => {
                stream = Some(s);
                break;
            }
            Err(e) => last_err = Some(e),
        }
    }
    let stream = match stream {
        Some(s) => s,
        None => {
            return Err(FetchError::Tcp(match last_err {
                Some(e) => io_message(&e),
