    let mut body = data[split + 4..].to_vec();
    let mut status = 0u16;
    for line in headers.lines() {
        if line.starts_with("HTTP/") {
            if let Some(code) = line.split_whitespace().nth(1) {
                status = code.parse().unwrap_or(0);
            }
        }
    }
    let chunked = headers.to_lowercase().contains("transfer-encoding: chunked");
    if chunked {
        body = dechunk(&body);
    }
    if (300..400).contains(&status) {
        if let Some(location) = header_value(&headers, "location") {
            let next = if location.starts_with("http") {
                location
            } else {
                format!("{}/{}", url.trim_end_matches('/'), location)
            };
            return get(&next);
        }
    }
    if status != 200 {
        return Err(FetchError::Io(format!("HTTP status {}", status)));
    }
    Ok(body)
}

fn header_value(headers: &str, name: &str) -> Option<String> {
    for line in headers.lines() {
        if let Some((k, v)) = line.split_once(':') {
            if k.trim().eq_ignore_ascii_case(name) {
                return Some(v.trim().to_string());
            }
        }
    }
    None
}

fn dechunk(data: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    let mut idx = 0usize;
    while idx < data.len() {
        let nl = match data[idx..].windows(2).position(|w| w == b"\r\n") {
            Some(p) => idx + p,
            None => break,
        };
        let size_str = String::from_utf_lossy(&data[idx..nl]).to_string();
        let size = usize::from_str_radix(size_str.trim().split(';').next().unwrap_or("0"), 16)
            .unwrap_or(0);
        idx = nl + 2;
        if size == 0 {
            break;
        }
        if idx + size > data.len() {
            out.extend_from_slice(&data[idx..]);
            break;
        }
        out.extend_from_slice(&data[idx..idx + size]);
        idx += size + 2;
    }
    out
}
