//! The `build` subcommand.

use crate::cli::OutputFormat;
use crate::config::{Config, DEFAULT_CSS_VERSION};
use crate::diag::Diagnostic;
use crate::log;

pub const FAVICON: &[u8] = include_bytes!("../assets/favicon.ico");

pub fn run(config: &Config, json_only: bool) -> Result<(), Diagnostic> {
    if json_only {
        // Only the artifacts JSON is (re)built; the site itself is untouched.
        create_dist_dir(&config.dist_dir)?;
        log::success(&format!(
            "Your site build is located in `{}`.",
            config.dist_dir
        ));
        return Ok(());
    }

    // Inspect the project so we can fill in metadata later on.
    if let Some(result) = crate::project::detect() {
        if let Err(stderr) = result {
            let manifest = std::env::current_dir()
                .unwrap_or_else(|_| std::path::PathBuf::from("."))
                .join("Cargo.toml");
            log::print_warning(&crate::project::warn_metadata_failure(&manifest, &stderr));
        }
    }

    create_dist_dir(&config.dist_dir)?;

    if config.styles.favicon.is_none() {
        let path = std::path::Path::new(&config.dist_dir).join("favicon.ico");
        std::fs::write(&path, FAVICON)?;
    }

    fetch_theme_css(config)?;

    crate::site::build(config)
}

pub fn create_dist_dir(dist_dir: &str) -> Result<(), Diagnostic> {
    std::fs::create_dir_all(dist_dir).map_err(|e| Diagnostic::error(e.to_string()))
}

/// Fetch the oranda CSS file that the site will use.
fn fetch_theme_css(config: &Config) -> Result<Vec<u8>, Diagnostic> {
    let version = config
        .styles
        .oranda_css_version
        .clone()
        .unwrap_or_else(|| DEFAULT_CSS_VERSION.to_string());
    let proxy = format!(
        "https://octolotl.axodotdev.host/downloads/axodotdev/oranda/{}/oranda.css",
        version
    );
    match crate::http_client::get(&proxy) {
        Ok(body) => Ok(body),
        Err(err) => {
            println!("Fetching from proxy encountered an error:");
            println!(" {}.", err.display(&proxy));
            println!(" Falling back to GitHub directly...");
            let github = format!(
                "https://api.github.com/repos/axodotdev/oranda/releases/download/{}/oranda.css",
                version
            );
            match crate::http_client::get(&github) {
                Ok(body) => Ok(body),
                Err(err) => {
                    let diag =
                        Diagnostic::error(err.display(&github)).with_causes(err.causes());
                    Err(diag)
                }
            }
        }
    }
}
