//! A minimal reimplementation of the `dialoguer` confirm prompt.

use std::io::{Read, Write};

#[derive(Debug)]
pub enum PromptError {
    NotTty,
}

impl std::fmt::Display for PromptError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            PromptError::NotTty => write!(f, "Error while prompting!: NotTTY"),
        }
    }
}

/// Ask a yes/no question, returning the answer.
pub fn confirm(prompt: &str, default: bool, note: Option<&str>) -> Result<bool, PromptError> {
    if !crate::term::is_tty(0) {
        return Err(PromptError::NotTty);
    }
    let theme_prefix = "\u{1b}[38;5;2m? >o_o<\u{1b}[39m";
    let hint = if default { "(Y/n)" } else { "(y/N)" };
    let mut stdout = std::io::stdout();
    let _ = write!(stdout, "\u{1b}[?25l\u{1b}[?25l\u{1b}[?25l{} {} {}  \n", theme_prefix, prompt, hint);
    if let Some(note) = note {
        let _ = write!(stdout, "\u{1b}[38;5;14m[\u{1b}[39m\u{1b}[38;5;14m{}\u{1b}[39m\u{1b}[38;5;14m]\u{1b}[39m\n", note);
    }
    let _ = stdout.flush();

    // Read a single character from stdin.
    let mut buf = [0u8; 1];
    let mut answer = default;
    if read_char(&mut buf) {
        match buf[0] {
            b'y' | b'Y' => answer = true,
            b'n' | b'N' => answer = false,
            b'\n' | b'\r' => answer = default,
            _ => answer = default,
        }
    }

    // Erase the prompt lines and print the final answer, mimicking dialoguer.
    let line_count = if note.is_some() { 2 } else { 1 };
    let _ = write!(stdout, "\u{1b}[{}A\u{1b}[80G\u{1b}[?25h\u{1b}[?25l\u{1b}[{}B\u{1b}[1G\u{1b}[1A\u{1b}[2K\u{1b}[1A\u{1b}[2K\u{1b}[?25l", line_count, line_count);
    let _ = write!(stdout, "\u{1b}[38;5;2m? >o_o<\u{1b}[39m {} {} {} ", prompt, hint, if answer { 'y' } else { 'n' });
    if let Some(note) = note {
        let _ = write!(stdout, "\n\u{1b}[38;5;14m[\u{1b}[39m\u{1b}[38;5;14m{}\u{1b}[39m\u{1b}[38;5;14m]\u{1b}[39m", note);
    }
    let _ = write!(stdout, "\u{1b}[{}A\u{1b}[{}G\u{1b}[?25h\u{1b}[?25l\u{1b}[{}B\u{1b}[1G\u{1b}[1A\u{1b}[2K\u{1b}[1A\u{1b}[2K\u{1b}[?25l\u{1b}[?25h", line_count, 80, line_count);
    let _ = write!(stdout, "\u{1b}[38;5;10m>\u{1b}[39m {} \u{1b}[38;5;14m{}\u{1b}[39m\n", prompt, if answer { "Yes" } else { "No" });
    let _ = stdout.flush();
    Ok(answer)
}

fn read_char(buf: &mut [u8; 1]) -> bool {
    let stdin = std::io::stdin();
    let mut lock = stdin.lock();
    lock.read_exact(buf).is_ok()
}
