//! The `generate` subcommand.

use crate::config::DEFAULT_DIST_DIR;
use crate::diag::Diagnostic;
use crate::log;

pub const TEMPLATE: &str = include_str!("../assets/web.yml.template");
pub const LINK_CHECK: &str = include_str!("../assets/link_check.yml");
pub const DEFAULT_OUTPUT: &str = ".github/workflows/web.yml";

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Ci {
    GitHub,
}

impl Ci {
    pub fn from_str(s: &str) -> Option<Ci> {
        match s {
            "github" => Some(Ci::GitHub),
            _ => None,
        }
    }
}

pub fn run(
    ci: Ci,
    output_path: Option<&str>,
    site_path: Option<&str>,
    verbose: bool,
) -> Result<(), Diagnostic> {
    match ci {
        Ci::GitHub => generate_ci(output_path, site_path, verbose),
    }
}

fn generate_ci(
    output_path: Option<&str>,
    site_path: Option<&str>,
    _verbose: bool,
) -> Result<(), Diagnostic> {
    log::info("Generating a CI deploy workflow for your site...");

    let link_check = crate::prompt::confirm(
        "Do you want to include a tool for checking generated hyperlinks?",
        true,
        Some("Read more about the link checker tool: https://github.com/untitaker/hyperlink"),
    )
    .map_err(|e| crate::diag::panic_diag("src/generate.rs:56:14", &e.to_string()))?;

    let latest = crate::prompt::confirm(
        "Do you want to always use the latest version of oranda?",
        false,
        Some("Using the latest version means you don't have to rerun this command when oranda updates, but it may also break your site if you use a lot of configuration!"),
    )
    .map_err(|e| crate::diag::panic_diag("src/generate.rs:56:14", &e.to_string()))?;

    let gitignore = crate::prompt::confirm(
        &format!(
            "Would you like to append the default destination directory (`{}`) to your .gitignore file?",
            DEFAULT_DIST_DIR
        ),
        false,
        None,
    )
    .map_err(|e| crate::diag::panic_diag("src/generate.rs:56:14", &e.to_string()))?;

    let path = output_path
        .map(std::path::PathBuf::from)
        .unwrap_or_else(|| std::path::PathBuf::from(DEFAULT_OUTPUT));

    let installer_url = if latest {
        "https://github.com/axodotdev/oranda/releases/latest/download/oranda-installer.sh"
    } else {
        "https://github.com/axodotdev/oranda/releases/download/v0.6.1/oranda-installer.sh"
    };

    let site_cd = match site_path {
        Some(site) => format!("          cd {}\n", site),
        None => String::new(),
    };
    let link_block = if link_check { LINK_CHECK } else { "" };

    let contents = TEMPLATE
