/// Guess the mime type of a path, falling back to `application/octet-stream`.
pub fn guess(path: &std::path::Path) -> &'static str {
    let ext = path
        .extension()
        .and_then(|e| e.to_str())
        .unwrap_or_default()
        .to_lowercase();
    match lookup(&ext) {
        Some(m) => m,
        None => "application/octet-stream",
    }
}
