{"command": "cd /workspace && cat > src/http_server.rs <<'RSEOF'
//! A small HTTP file server that reproduces the behaviour of the original's
//! `hyper` + `tower-http` based server.

use crate::diag::Diagnostic;
use crate::httpdate;
use crate::mime;
use std::io::{Read, Write};
use std::sync::{Arc, Condvar, Mutex};

pub const LIVERELOAD_PREFIX: &str = "/tower-livereload/long-name-to-avoid-collisions";
pub const LIVERELOAD_SCRIPT: &[u8] = include_bytes!("../assets/livereload.js");

/// Shared state used to notify long-polling clients about rebuilds.
#[derive(Default)]
pub struct Reload {
    state: Mutex<u64>,
    cond: Condvar,
}

impl Reload {
    pub fn new() -> Arc<Reload> {
        Arc::new(Reload::default())
    }

    pub fn notify(&self) {
        let mut state = self.state.lock().unwrap();
        *state += 1;
        self.cond.notify_all();
    }

    pub fn wait(&self, seen: u64) -> u64 {
        let mut state = self.state.lock().unwrap();
        while *state == seen {
            state = self.cond.wait(state).unwrap();
        }
        *state
    }
}

struct Request {
    method: String,
    path: String,
    version: String,
    headers: Vec<(String, String)>,
}

impl Request {
    fn header(&self, name: &str) -> Option<&str> {
        self.headers
            .iter()
            .find(|(k, _)| k.eq_ignore_ascii_case(name))
            .map(|(_, v)| v.as_str())
    }
}

struct Response {
    status: u16,
    reason: &'static str,
    headers: Vec<(String, String)>,
    body: Vec<u8>,
    chunked: bool,
}

impl Response {
    fn empty(status: u16, reason: &'static str) -> Response {
        Response {
            status,
            reason,
            headers: Vec::new(),
            body: Vec::new(),
            chunked: false,
        }
    }

    fn header(&mut self, name: &str, value: impl Into<String>) {
        self.headers.push((name.to_string(), value.into()));
    }

    fn write(&self, version: &str, out: &mut dyn Write) -> std::io::Result<()> {
        let mut head = format!("HTTP/{} {} {}\r\n", version, self.status, self.reason);
        for (k, v) in &self.headers {
            head.push_str(&format!("{}: {}\r\n", k, v));
        }
        head.push_str("\r\n");
        out.write_all(head.as_bytes())?;
        if self.chunked {
            if !self.body.is_empty() {
                out.write_all(format!("{:x}\r\n", self.body.len()).as_bytes())?;
                out.write_all(&self.body)?;
                out.write_all(b"\r\n")?;
            }
            out.write_all(b"0\r\n\r\n")?;
        } else {
            out.write_all(&self.body)?;
        }
        out.flush()
    }
}

/// Start serving `dist_dir` on 127.0.0.1:`port`.
///
/// Returns an error shaped like the panic the original produces when the port
/// can't be bound, or when there is no build to serve.
pub fn check_build(dist_dir: &str) -> Result<(), Diagnostic> {
    if !std::path::Path::new(dist_dir).exists() {
        return Err(Diagnostic::error(format!(
            "Could not find a build in {}",
            dist_dir
        ))
        .with_help("Did you remember to run `oranda build`?"));
    }
    Ok(())
}

pub fn start(
    port: u16,
    dist_dir: String,
    livereload: bool,
    reload: Arc<Reload>,
) -> Result<(), Diagnostic> {
    let listener = std::net::TcpListener::bind(("127.0.0.1", port)).map_err(|e| {
        // Mirror hyper's panic message when the listener can't be created.
        Diagnostic::error(format!(
            "error binding to 127.0.0.1:{}: error creating server listener: {}",
            port,
            e
        ))
        .with_causes(vec![format!("at hyper server.rs:81:13")])
    })?;

    std::thread::spawn(move || {
        for conn in listener.incoming() {
            let stream = match conn {
                Ok(s) => s,
                Err(_) => continue,
            };
            let dist_dir = dist_dir.clone();
            let reload = reload.clone();
            std::thread::spawn(move || {
                let _ = handle_connection(stream, &dist_dir, livereload, reload);
            });
        }
    });
    Ok(())
}

fn handle_connection(
    mut stream: std::net::TcpStream,
    dist_dir: &str,
    livereload: bool,
    reload: Arc<Reload>,
) -> std::io::Result<()> {
    let mut buf: Vec<u8> = Vec::new();
    loop {
        let req = match read_request(&mut stream, &mut buf) {
            Some(r) => r,
            None => return Ok(()),
        };
        let version = req.version.clone();
        let keep_alive = !req.header("connection").map(|v| v.eq_ignore_ascii_case("close")).unwrap_or(false);
        let resp = handle_request(&req, dist_dir, livereload, &reload);
        resp.write(&version, &mut stream)?;
        if !keep_alive {
            return Ok(());
        }
    }
}

fn read_request(stream: &mut std::net::TcpStream, buf: &mut Vec<u8>) -> Option<Request> {
    loop {
        if let Some(pos) = find_header_end(buf) {
            let head = String::from_utf_lossy(&buf[..pos]).to_string();
            let extra = buf.drain(..pos + 4);
            let _ = extra;
            return parse_request(&head);
        }
        let mut chunk = [0u8; 8192];
        let n = stream.read(&mut chunk).ok()?;
        if n == 0 {
            return None;
        }
        buf.extend_from_slice(&chunk[..n]);
    }
}

fn find_header_end(buf: &[u8]) -> Option<usize> {
    buf.windows(4).position(|w| w == b"\r\n\r\n")
}

fn parse_request(head: &str) -> Option<Request> {
    let mut lines = head.split("\r\n");
    let first = lines.next()?;
    let mut parts = first.split_whitespace();
    let method = parts.next()?.to_string();
    let path = parts.next()?.to_string();
    let version = parts.next().unwrap_or("HTTP/1.1").to_string();
    if !method.chars().all(|c| c.is_ascii_uppercase()) || !path.starts_with('/') {
        return None;
    }
    let mut headers = Vec::new();
    for line in lines {
        if line.is_empty() {
            continue;
        }
        if let Some((k, v)) = line.split_once(':') {
            headers.push((k.trim().to_string(), v.trim().to_string()));
        }
    }
    Some(Request {
        method,
        path,
        version,
        headers,
    })
}

fn handle_request(req: &Request, dist_dir: &str, livereload: bool, reload: &Arc<Reload>) -> Response {
    let now = httpdate::format_http_date(httpdate::now_unix());

    if livereload {
        if req.path == format!("{}/long-poll", LIVERELOAD_PREFIX) {
            let _ = reload.wait(0);
            let mut resp = Response::empty(200, "OK");
            resp.header("content-type", "text/plain");
            resp.header("transfer-encoding", "chunked");
            resp.header("date", now);
            resp.chunked = true;
            return resp;
        }
        if req.path == format!("{}/back-up", LIVERELOAD_PREFIX) {
            let mut resp = Response::empty(200, "OK");
            resp.header("content-type", "text/plain");
            resp.header("transfer-encoding", "chunked");
            resp.header("date", now);
            resp.chunked = true;
            resp.body = b"Ok".to_vec();
            return resp;
        }
    }

    let method = req.method.as_str();
    if method != "GET" && method != "HEAD" {
        let mut resp = Response::empty(405, "Method Not Allowed");
        resp.header("allow", "GET,HEAD");
        resp.header("content-length", "0");
        resp.header("date", now);
        return resp;
    }

    // Strip the query string and refuse path traversal.
    let raw_path = req.path.split('?').next().unwrap_or("/");
    let mut path = raw_path.to_string();
    while path.starts_with("//") {
        path = path[1..].to_string();
    }
    if path.contains("..") {
        return not_found(&now, &req.version);
    }

    let mut fs_path = std::path::PathBuf::from(dist_dir);
    let relative = path.trim_start_matches('/');
    if !relative.is_empty() {
        fs_path.push(relative);
    } else {
        fs_path.push("index.html");
    }

    let meta = match std::fs::metadata(&fs_path) {
        Ok(m) => m,
        Err(_) => return not_found(&now, &req.version),
    };
    if meta.is_dir() {
        return not_found(&now, &req.version);
    }

    let mime_type = mime::guess(&fs_path);
    let modified = meta
        .modified()
        .ok()
        .and_then(|m| m.duration_since(std::time::UNIX_EPOCH).ok())
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    let last_modified = httpdate::format_http_date(modified);
    let total = meta.len();

    // Conditional requests
    if let Some(ims) = req.header("if-modified-since") {
        if let Some(parsed) = httpdate::parse_http_date(ims) {
            if parsed >= modified {
                let mut resp = Response::empty(304, "Not Modified");
                resp.header("date", now);
                return resp;
            }
        }
    }

    let mut resp = Response::empty(200, "OK");
    resp.header("content-type", mime_type);
    resp.header("accept-ranges", "bytes");
    resp.header("last-modified", last_modified.clone());

    // Range handling
    if let Some(range) = req.header("range") {
        match parse_ranges(range, total) {
            RangeResult::Invalid => {
                let mut resp = Response::empty(416, "Range Not Satisfiable");
                resp.header("content-type", mime_type);
                resp.header("accept-ranges", "bytes");
                resp.header("last-modified", last_modified);
                resp.header("content-range", format!("bytes */{}", total));
                resp.header("content-length", "0");
                resp.header("date", now);
                return resp;
            }
            RangeResult::Multipart => {
                let mut resp = Response::empty(416, "Range Not Satisfiable");
                resp.header("content-type", mime_type);
                resp.header("accept-ranges", "bytes");
                resp.header("last-modified", last_modified);
                resp.header("content-range", format!("bytes */{}", total));
                resp.header("content-length", "37");
                resp.header("date", now);
                resp.body = b"Cannot serve multipart range requests".to_vec();
                return resp;
            }
            RangeResult::Single((start, end)) => {
                resp.header(
                    "content-range",
                    format!("bytes {}-{}/{}", start, end, total),
                );
                resp.status = 206;
                resp.reason = "Partial Content";
                resp.body = read_range(&fs_path, start, end);
                resp.header("content-length", resp.body.len().to_string());
                resp.header("date", now);
                return resp;
            }
        }
    }

    if !resp.body.is_empty() {
        // unreachable
    }
    let data = match std::fs::read(&fs_path) {
        Ok(d) => d,
        Err(_) => return not_found(&now, &req.version),
    };
    let mut body = data;
    if livereload && mime_type == "text/html" && !body.is_empty() && method != "HEAD" {
        body.extend_from_slice(LIVERELOAD_SCRIPT);
    }
    resp.header("content-length", body.len().to_string());
    resp.header("date", now);
    resp.body = body;
    resp
}

fn not_found(now: &str, _version: &str) -> Response {
    let mut resp = Response::empty(404, "Not Found");
    resp.header("content-length", "0");
    resp.header("date", now.to_string());
    resp
}

enum RangeResult {
    Single((u64, u64)),
    Multipart,
    Invalid,
}

fn parse_ranges(header: &str, total: u64) -> RangeResult {
    let header = header.trim();
    let (unit, spec) = match header.split_once('=') {
        Some((u, s)) => (u.trim(), s.trim()),
        None => return RangeResult::Invalid,
    };
    if unit != "bytes" {
        return RangeResult::Invalid;
    }
    let parts: Vec<&str> = spec.split(',').collect();
    if parts.len() > 1 {
        return RangeResult::Multipart;
    }
    let part = parts[0].trim();
    if let Some((a, b)) = part.split_once('-') {
        let first = a.trim();
        let last = b.trim();
        if first.is_empty() {
            // suffix range
            let n: u64 = match last.parse() {
                Ok(n) => n,
                Err(_) => return RangeResult::Invalid,
            };
            if n == 0 || total == 0 {
                return RangeResult::Invalid;
            }
            let start = if n >= total { 0 } else { total - n };
            return RangeResult::Single((start, total - 1));
        }
        let start: u64 = match first.parse() {
