    // Conditional requests
    if let Some(ims) = req.header("if-modified-since") {
        if let Some(parsed) = httpdate::parse_http_date(ims) {
            if parsed >= modified {
                let mut resp = Response::empty(304, "Not Modified");
                resp.header("date", now);
                return resp;
            }
        }
    }

    let mut resp = Response::empty(200, "OK");
    resp.header("content-type", mime_type);
    resp.header("accept-ranges", "bytes");
    resp.header("last-modified", last_modified.clone());

    // Range handling
    if let Some(range) = req.header("range") {
        match parse_ranges(range, total) {
            RangeResult::Invalid => {
                let mut resp = Response::empty(416, "Range Not Satisfiable");
                resp.header("content-type", mime_type);
                resp.header("accept-ranges", "bytes");
                resp.header("last-modified", last_modified);
                resp.header("content-range", format!("bytes */{}", total));
                resp.header("content-length", "0");
                resp.header("date", now);
                return resp;
            }
            RangeResult::Multipart => {
                let mut resp = Response::empty(416, "Range Not Satisfiable");
                resp.header("content-type", mime_type);
                resp.header("accept-ranges", "bytes");
                resp.header("last-modified", last_modified);
                resp.header("content-range", format!("bytes */{}", total));
                resp.header("content-length", "37");
                resp.header("date", now);
                resp.body = b"Cannot serve multipart range requests".to_vec();
                return resp;
            }
            RangeResult::Single((start, end)) => {
                resp.header(
                    "content-range",
                    format!("bytes {}-{}/{}", start, end, total),
                );
                resp.status = 206;
                resp.reason = "Partial Content";
                resp.body = read_range(&fs_path, start, end);
                resp.header("content-length", resp.body.len().to_string());
                resp.header("date", now);
                return resp;
            }
        }
    }

    if !resp.body.is_empty() {
        // unreachable
    }
    let data = match std::fs::read(&fs_path) {
        Ok(d) => d,
        Err(_) => return not_found(&now, &req.version),
    };
    let mut body = data;
    if livereload && mime_type == "text/html" && !body.is_empty() && method != "HEAD" {
        body.extend_from_slice(LIVERELOAD_SCRIPT);
    }
    resp.header("content-length", body.len().to_string());
    resp.header("date", now);
    resp.body = body;
    resp
}

fn not_found(now: &str, _version: &str) -> Response {
    let mut resp = Response::empty(404, "Not Found");
    resp.header("content-length", "0");
    resp.header("date", now.to_string());
    resp
}

enum RangeResult {
    Single((u64, u64)),
    Multipart,
    Invalid,
}

fn parse_ranges(header: &str, total: u64) -> RangeResult {
    let header = header.trim();
    let (unit, spec) = match header.split_once('=') {
        Some((u, s)) => (u.trim(), s.trim()),
        None => return RangeResult::Invalid,
    };
    if unit != "bytes" {
        return RangeResult::Invalid;
    }
    let parts: Vec<&str> = spec.split(',').collect();
    if parts.len() > 1 {
        return RangeResult::Multipart;
    }
    let part = parts[0].trim();
    if let Some((a, b)) = part.split_once('-') {
        let first = a.trim();
        let last = b.trim();
        if first.is_empty() {
            // suffix range
            let n: u64 = match last.parse() {
                Ok(n) => n,
                Err(_) => return RangeResult::Invalid,
            };
            if n == 0 || total == 0 {
                return RangeResult::Invalid;
            }
            let start = if n >= total { 0 } else { total - n };
            return RangeResult::Single((start, total - 1));
        }
        let start: u64 = match first.parse() {
            Ok(n) => n,
            Err(_) => return RangeResult::Invalid,
        };
        if start >= total {
            return RangeResult::Invalid;
        }
        let end = if last.is_empty() {
            total - 1
        } else {
            match last.parse::<u64>() {
                Ok(e) => {
                    if e < start {
                        return RangeResult::Invalid;
                    }
                    e.min(total - 1)
                }
                Err(_) => return RangeResult::Invalid,
            }
        };
        return RangeResult::Single((start, end));
    }
    RangeResult::Invalid
}

fn read_range(path: &std::path::Path, start: u64, end: u64) -> Vec<u8> {
    use std::io::{Seek, SeekFrom};
    let Ok(mut f) = std::fs::File::open(path) else {
        return Vec::new();
    };
    let _ = f.seek(SeekFrom::Start(start));
    let len = (end - start + 1) as usize;
    let mut buf = vec![0u8; len];
    let mut read = 0usize;
    while read < len {
        match f.read(&mut buf[read..]) {
            Ok(0) => break,
            Ok(n) => read += n,
            Err(_) => break,
        }
    }
    buf.truncate(read);
    buf
}
