//! A polling file watcher.

use std::collections::HashMap;
use std::path::PathBuf;

pub struct Watcher {
    paths: Vec<PathBuf>,
    mtimes: HashMap<PathBuf, Option<i64>>,
}

fn mtime_of(path: &std::path::Path) -> Option<i64> {
    std::fs::metadata(path)
        .ok()
        .and_then(|m| m.modified().ok())
        .and_then(|m| m.duration_since(std::time::UNIX_EPOCH).ok())
        .map(|d| d.as_secs() as i64)
}

impl Watcher {
    /// Create a watcher for the given paths, dropping any that don't exist.
    pub fn new(paths: Vec<PathBuf>) -> Watcher {
        let mut existing = Vec::new();
        for p in paths {
            if p.exists() {
                existing.push(p.clone());
            }
        }
        let mtimes = existing
            .iter()
            .map(|p| (p.clone(), mtime_of(p)))
            .collect();
        Watcher {
            paths: existing,
            mtimes,
        }
    }

    /// Block until one of the watched paths changes, returning them.
    pub fn wait(&mut self) -> Vec<PathBuf> {
        loop {
            for path in &self.paths {
                let current = mtime_of(path);
                if current != self.mtimes.get(path).cloned().flatten() {
                    self.mtimes.insert(path.clone(), current);
                    return vec![path.clone()];
                }
            }
            std::thread::sleep(std::time::Duration::from_millis(100));
        }
    }
}
