use cli::{build_cli, OutputFormat};
use diag::Diagnostic;

fn main() {
    let matches = build_cli().get_matches();
    let verbose = matches.get_flag("verbose");
    let format = match matches.get_one::<String>("output-format").map(|s| s.as_str()) {
        Some("json") => OutputFormat::Json,
        _ => OutputFormat::Human,
    };

    let result = dispatch(&matches, verbose, format);
    if let Err(diag) = result {
        log::print_diagnostic(&diag, format);
        std::process::exit(255);
    }
}

fn dispatch(
    matches: &clap::ArgMatches,
    verbose: bool,
    format: OutputFormat,
) -> Result<(), Diagnostic> {
    if verbose {
        log::debug("verbose logging enabled");
    }
    let (name, sub) = match matches.subcommand() {
        Some(sc) => sc,
        None => return Ok(()),
    };
    match name {
        "build" => {
            let config = load_config(verbose, format)?;
            let json_only = sub.get_flag("json-only");
            commands::build::run(&config, json_only)
        }
        "dev" => {
            let config = load_config(verbose, format)?;
            let port = sub.get_one::<u16>("port").copied();
            let no_first_build = sub.get_flag("no-first-build");
            let include_paths: Vec<String> = sub
                .get_many::<String>("include-paths")
                .map(|vals| vals.cloned().collect())
                .unwrap_or_default();
            commands::dev::run(&config, config_path(), port.unwrap_or(7979), no_first_build, &include_paths)
        }
        "serve" => {
            let config = load_config(verbose, format)?;
            let port = sub.get_one::<u16>("port").copied().unwrap_or(7979);
            commands::serve::run(&config, port)
        }
        "generate" => {
            let (gen_name, gen) = match sub.subcommand() {
                Some(sc) => sc,
                None => return Ok(()),
            };
            match gen_name {
                "ci" => {
                    let ci = gen
                        .get_one::<String>("ci")
                        .and_then(|s| commands::generate::Ci::from_str(s))
                        .unwrap_or(commands::generate::Ci::GitHub);
                    let output_path = gen.get_one::<String>("output-path").cloned();
                    let site_path = gen.get_one::<String>("site-path").cloned();
                    commands::generate::run(ci, output_path.as_deref(), site_path.as_deref(), verbose)
                }
                _ => Ok(()),
            }
        }
        _ => Ok(()),
    }
}

fn config_path() -> Option<&'static str> {
    if std::path::Path::new("./oranda.json").exists() {
        Some("oranda.json")
    } else {
        None
    }
}

/// Read and parse `oranda.json`, if present.
fn load_config(verbose: bool, _format: OutputFormat) -> Result<config::Config, Diagnostic> {
    let path = Path::new("./oranda.json");
    if !path.exists() {
        if verbose {
            log::debug("No config found, using default values");
        }
        return Ok(config::Config::from_layer(config::OrandaLayer::default()));
    }
    let text = std::fs::read_to_string(path)?;
    let layer: config::OrandaLayer = serde_json::from_str(&text).map_err(|e| {
        Diagnostic::error("failed to parse JSON")
            .with_causes(vec![e.to_string()])
            .with_label_from_json_error(&e, &text)
            .with_filename("./oranda.json")
    })?;
    Ok(config::Config::from_layer(layer))
}

use std::path::Path;

impl Diagnostic {
    fn with_label_from_json_error(
        mut self,
        err: &serde_json::Error,
        _text: &str,
    ) -> Diagnostic {
        let line = err.line();
        let column = err.column();
        if column == 0 {
            self.filename = Some(String::new());
            return self;
        }
        let text = _text;
        let mut offset = 0usize;
        for (idx, l) in text.split('\n').enumerate() {
            if idx + 1 == line {
                offset += column - 1;
                break;
            }
            offset += l.len() + 1;
        }
        self.labels.push(diag::Label {
            offset,
            length: 1,
        });
        self
    }
}
