    if !no_first_build {
        if let Err(diag) = crate::commands::build::run(config, false) {
            log::print_diagnostic(&diag, crate::cli::OutputFormat::Human);
            return Err(diag);
        }
    }

    let livereload_reload = reload.clone();
    match crate::commands::serve::serve_for_dev(config, port, true) {
        Ok(_) => {
            let _ = livereload_reload;
            log::success(&format!(
                "Your project is available at: http://127.0.0.1:{}",
                port
            ));
        }
        Err(diag) => {
            let rendered = crate::commands::serve::unwrap_panic(&debug_of_build_not_found(config));
            let _ = diag;
            log::print_diagnostic(&crate::diag::Diagnostic::error("oranda panicked.")
                .with_causes(rendered.causes), crate::cli::OutputFormat::Human);
        }
    }

    loop {
        let changed = watcher.wait();
        let display: Vec<String> = changed
            .iter()
            .map(|p| p.display().to_string())
            .collect();
        log::info(&format!("Path(s) {:?} changed, rebuilding...", display));
        if crate::commands::build::run(config, false).is_ok() {
            reload.notify();
        }
    }
}

/// Reproduce the `Debug` output of oranda's own error enum.
fn debug_of_build_not_found(config: &Config) -> String {
    format!("BuildNotFound {{ dist_dir: {:?} }}", config.dist_dir)
}

/// Lexically resolve `path` against the current directory, then express it
/// relative to it when possible.
pub fn normalize_string(path: &str) -> String {
    normalize(path).display().to_string()
}

pub fn normalize(path: &str) -> PathBuf {
    let p = Path::new(path);
    if p.is_absolute() {
        return p.to_path_buf();
    }
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let joined = cwd.join(p);
    let abs = lexical_normalize(&joined);
    match abs.strip_prefix(&cwd) {
        Ok(rel) => rel.to_path_buf(),
        Err(_) => p.to_path_buf(),
    }
}

fn lexical_normalize(path: &Path) -> PathBuf {
    let mut parts: Vec<std::ffi::OsString> = Vec::new();
    for comp in path.components() {
        match comp {
            Component::RootDir => {
                parts.clear();
                parts.push(std::ffi::OsString::from("/"));
            }
            Component::CurDir => {}
            Component::ParentDir => {
                if parts.len() > 1 && parts[parts.len() - 1] != std::ffi::OsString::from("..") {
                    parts.pop();
                } else if parts.len() == 1 && parts[0] == std::ffi::OsString::from("/") {
                    // Can't go above the root
                } else {
                    parts.push(std::ffi::OsString::from(".."));
                }
            }
            Component::Normal(c) => parts.push(c.to_os_string()),
            Component::Prefix(_) => {}
        }
    }
    let mut out = PathBuf::new();
    for part in &parts {
        if part == std::ffi::OsString::from("/") {
            out = PathBuf::from("/");
        } else {
            out.push(part);
        }
    }
    if out.as_os_str().is_empty() {
        PathBuf::from(".")
    } else {
        out
    }
}
