/// are longer than the available width.
fn wrap_line(line: &str, width: usize) -> Vec<String> {
    if width == 0 {
        return vec![line.to_string()];
    }
    if line.is_empty() {
        return vec![String::new()];
    }
    let bytes = line.as_bytes();
    let mut out: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut cur_len = 0usize;
    let mut started = false;
    let mut idx = 0usize;
    while idx < bytes.len() {
        let ws_start = idx;
        while idx < bytes.len() && bytes[idx].is_ascii_whitespace() {
            idx += 1;
        }
        let ws = &line[ws_start..idx];
        let w_start = idx;
        while idx < bytes.len() && !bytes[idx].is_ascii_whitespace() {
            idx += 1;
        }
        let word = &line[w_start..idx];
        if word.is_empty() {
            cur.push_str(ws);
            cur_len += display_width(ws);
            started = true;
            continue;
        }
        let wl = display_width(word);
        let wsl = display_width(ws);
        if !started {
            cur.push_str(ws);
            cur_len = wsl;
            started = true;
        } else if cur_len + wsl + wl > width {
            out.push(cur.trim_end().to_string());
            cur.clear();
            cur_len = 0;
        } else {
            cur.push_str(ws);
            cur_len += wsl;
        }
        if wl > width {
            let mut rest = word;
            while display_width(rest) > width {
                let (chunk, remainder) = split_at_width(rest, width);
                out.push(cur.clone());
                cur = chunk.to_string();
                cur_len = display_width(chunk);
                rest = remainder;
            }
            cur.push_str(rest);
            cur_len += display_width(rest);
        } else {
            cur.push_str(word);
            cur_len += wl;
        }
    }
    out.push(cur);
    out
}

'''
