```rust
fn wrap_line(line: &str, width: usize) -> Vec<String> {
    if width == 0 { return vec![line.to_string()]; }
    if line.is_empty() { return vec![String::new()]; }
    // tokenize into (leading_ws, word) pairs
    let mut out = Vec::new();
    let mut cur = String::new();
    let mut cur_len = 0usize;
    let mut started = false;   // whether cur has content (or leading ws)
    let bytes = line.as_bytes();
    let mut idx = 0usize;
    while idx < bytes.len() {
        // gather whitespace run
        let ws_start = idx;
        while idx < bytes.len() && bytes[idx].is_ascii_whitespace() { idx += 1; }
        let ws = &line[ws_start..idx];
        // gather word
        let w_start = idx;
        while idx < bytes.len() && !bytes[idx].is_ascii_whitespace() { idx += 1; }
        let word = &line[w_start..idx];
        if word.is_empty() {
            // trailing whitespace only
            if started { cur.push_str(ws); cur_len += ws.len(); }
            else { cur.push_str(ws); cur_len += ws.len(); started = true; }
            continue;
        }
        let wl = display_width(word);
        let wsl = display_width(ws);
        if !started {
            // first word: leading ws is part of the line
            if wl + wsl > width {
                // hard break: emit leading ws first? hmm
                ...
            }
            cur.push_str(ws); cur.push_str(word);
            cur_len = wsl + wl;
            started = true;
            continue;
        }
        if cur_len + wsl + wl <= width {
            cur.push_str(ws); cur.push_str(word);
            cur_len += wsl + wl;
        } else {
            out.push(cur.trim_end().to_string());
            cur.clear(); started = false;
            // hard break if the word alone exceeds the width
            if wl > width {
                let mut rest = word;
                while display_width(rest) > width {
                    let (chunk, remainder) = split_at_width(rest, width);
                    out.push(chunk.to_string());
                    rest = remainder;
                }
                cur = rest.to_string();
                cur_len = display_width(rest);
                started = true;
            } else {
                cur = word.to_string();
                cur_len = wl;
                started = true;
            }
        }
    }
    out.push(cur);
    out
}
```
