/// Greedy word wrapping that preserves leading whitespace and breaks words that
/// are longer than the available width.
fn wrap_line(line: &str, width: usize) -> Vec<String> {
    if width == 0 {
        return vec![line.to_string()];
    }
    let bytes = line.as_bytes();
    let is_ws = |c: u8| c.is_ascii_whitespace();
    // Leading whitespace is always preserved verbatim.
    let mut idx = 0usize;
    while idx < bytes.len() && is_ws(bytes[idx]) {
        idx += 1;
    }
    let lead = &line[..idx];
    let mut pairs: Vec<(&str, &str)> = Vec::new();
    let mut trailing_ws: Option<&str> = None;
    while idx < bytes.len() {
        let ws_start = idx;
        while idx < bytes.len() && is_ws(bytes[idx]) {
            idx += 1;
        }
        let ws = &line[ws_start..idx];
        if idx >= bytes.len() {
            trailing_ws = Some(ws);
            break;
        }
        let w_start = idx;
        while idx < bytes.len() && !is_ws(bytes[idx]) {
            idx += 1;
        }
        pairs.push((ws, &line[w_start..idx]));
    }

    let mut out: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut cur_len = 0usize;
    if !lead.is_empty() {
        cur.push_str(lead);
        cur_len += display_width(lead);
    }
    let mut first_word = true;
    for (ws, word) in pairs {
        let wl = display_width(word);
        let wsl = display_width(ws);
        if first_word {
            first_word = false;
            if wl > width {
                if cur.trim().is_empty() {
                    cur.clear();
                    cur_len = 0;
                }
                let mut rest = word;
                while display_width(rest) > width {
                    let (chunk, remainder) = split_at_width(rest, width);
                    if !cur.is_empty() {
                        out.push(cur.clone());
                    }
                    cur = chunk.to_string();
                    cur_len = display_width(chunk);
                    rest = remainder;
                }
                cur.push_str(rest);
                cur_len += display_width(rest);
                continue;
            }
            cur.push_str(word);
            cur_len += wl;
        } else if cur_len + wsl + wl <= width {
            cur.push_str(ws);
            cur.push_str(word);
            cur_len += wsl + wl;
