new = '''fn handle_request(req: &Request, dist_dir: &str, livereload: bool, reload: &Arc<Reload>) -> Response {
    let now = httpdate::format_http_date(httpdate::now_unix());

    if livereload {
        if req.path == format!("{}/long-poll", LIVERELOAD_PREFIX) {
            let _ = reload.wait(0);
            let mut resp = Response::empty(200, "OK");
            resp.header("content-type", "text/plain");
            resp.header("transfer-encoding", "chunked");
            resp.header("date", now);
            resp.chunked = true;
            return resp;
        }
        if req.path == format!("{}/back-up", LIVERELOAD_PREFIX) {
            let mut resp = Response::empty(200, "OK");
            resp.header("content-type", "text/plain");
            resp.header("transfer-encoding", "chunked");
            resp.header("date", now);
            resp.chunked = true;
            resp.body = b"Ok".to_vec();
            return resp;
        }
    }

    let method = req.method.as_str();
    if method != "GET" && method != "HEAD" {
        let mut resp = Response::empty(405, "Method Not Allowed");
        resp.header("allow", "GET,HEAD");
        resp.header("content-length", "0");
        resp.header("date", now);
        return resp;
    }

    // Strip the query string and decode percent escapes.
    let raw_path = req.path.split('?').next().unwrap_or("/");
    let decoded = percent_decode(raw_path);
    if decoded.contains('\\u{0}') {
        let mut resp = Response::empty(500, "Internal Server Error");
        resp.header("content-type", "text/plain; charset=utf-8");
        resp.header("content-length", "68");
        resp.header("date", now);
        resp.body =
            b"Unhandled internal error: file name contained an unexpected NUL byte".to_vec();
        return resp;
    }
    let had_trailing_slash = decoded.ends_with('/');
    let segments: Vec<&str> = decoded.split('/').filter(|s| !s.is_empty()).collect();
    if segments.iter().any(|s| *s == "..") {
        return not_found(&now);
    }
    let clean = segments.join("/");

    let mut fs_path = std::path::PathBuf::from(dist_dir);
    if clean.is_empty() {
        fs_path.push("index.html");
    } else {
        fs_path.push(&clean);
    }

    match std::fs::metadata(&fs_path) {
        Err(_) => return not_found(&now),
        Ok(meta) => {
            if meta.is_dir() {
                if had_trailing_slash {
                    fs_path.push("index.html");
                    if std::fs::metadata(&fs_path).is_err() {
                        return not_found(&now);
                    }
                } else {
                    let mut resp = Response::empty(307, "Temporary Redirect");
                    resp.header("location", format!("/{}/", clean));
                    resp.header("content-length", "0");
                    resp.header("date", now);
                    return resp;
                }
            }
        }
    }

    serve_file(req, &fs_path, &now)
}

fn serve_file(req: &Request, fs_path: &std::path::Path, now: &str) -> Response {
    let meta = match std::fs::metadata(fs_path) {
        Ok(m) => m,
        Err(_) => return not_found(now),
    };
    let mime_type = mime::guess(fs_path);
    let modified = meta
        .modified()
        .ok()
        .and_then(|m| m.duration_since(std::time::UNIX_EPOCH).ok())
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    let last_modified = httpdate::format_http_date(modified);
    let total = meta.len();

    if let Some(ims) = req.header("if-modified-since") {
        if let Some(parsed) = httpdate::parse_http_date(ims) {
            if parsed >= modified {
                let mut resp = Response::empty(304, "Not Modified");
                resp.header("date", now);
                return resp;
            }
        }
    }

    let mut resp = Response::empty(200, "OK");
    resp.header("content-type", mime_type);
    resp.header("accept-ranges", "bytes");
    resp.header("last-modified", last_modified.clone());

    if let Some(range) = req.header("range") {
        match parse_ranges(range, total) {
            RangeResult::Invalid => {
                resp.status = 416;
                resp.reason = "Range Not Satisfiable";
                resp.header("content-range", format!("bytes */{}", total));
                resp.header("content-length", "0");
                resp.header("date", now);
                return resp;
            }
            RangeResult::Multipart => {
                resp.status = 416;
                resp.reason = "Range Not Satisfiable";
                resp.header("content-range", format!("bytes */{}", total));
                resp.header("content-length", "37");
                resp.header("date", now);
                resp.body = b"Cannot serve multipart range requests".to_vec();
                return resp;
            }
            RangeResult::Single((start, end)) => {
                resp.header(
                    "content-range",
                    format!("bytes {}-{}/{}", start, end, total),
                );
                resp.status = 206;
                resp.reason = "Partial Content";
                resp.body = read_range(fs_path, start, end);
                resp.header("content-length", resp.body.len().to_string());
                resp.header("date", now);
                return resp;
            }
        }
    }

    let data = match std::fs::read(fs_path) {
        Ok(d) => d,
        Err(_) => return not_found(now),
    };
    let mut body = data;
    if req.livereload && mime_type == "text/html" && !body.is_empty() && req.method != "HEAD" {
        body.extend_from_slice(LIVERELOAD_SCRIPT);
    }
    resp.header("content-length", body.len().to_string());
    resp.header("date", now);
    resp.body = body;
    resp
}

/// Percent-decode a path, leaving invalid escapes untouched.
