{"command": "cd /workspace && cat > src/prompt.rs <<'RSEOF'
//! A minimal reimplementation of the `dialoguer` confirm prompt, including the
//! ANSI escape sequences it writes.

use std::io::Write;

#[derive(Debug)]
pub enum PromptError {
    NotTty,
}

impl std::fmt::Display for PromptError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            PromptError::NotTty => write!(f, "Error while prompting!: NotTTY"),
        }
    }
}

const HIDE: &str = "\x1b[?25l";
const SHOW: &str = "\x1b[?25h";

fn prompt_line(prompt: &str, hint: &str, typed: &str) -> String {
    format!(
        "\x1b[38;5;2m? >o_o<\x1b[39m {} ({}) {} \r\n",
        prompt, hint, typed
    )
}

fn note_line(note: &str) -> String {
    format!(
        "\x1b[38;5;14m[\x1b[39m\x1b[38;5;14m{}\x1b[39m\x1b[38;5;14m]\x1b[39m\r\n",
        note
    )
}

fn final_line(prompt: &str, answer: bool) -> String {
    format!(
        "\x1b[38;5;10m>\x1b[39m {} \x1b[38;5;14m{}\x1b[39m\r\n",
        prompt,
        if answer { "Yes" } else { "No" }
    )
}

fn visible_width(s: &str) -> usize {
    s.chars().count()
}

/// Ask a yes/no question, returning the answer.
pub fn confirm(prompt: &str, default: bool, note: Option<&str>, first: bool) -> Result<bool, PromptError> {
    if !crate::term::is_tty(0) {
        return Err(PromptError::NotTty);
    }
    let hint = if default { "(Y/n)" } else { "(y/N)" };
    let base_col = visible_width(prompt) + 16;
    let lines = lines_occupied(prompt, note);
    let mut stderr = std::io::stderr();

    let mut out = String::new();
    if first {
        out.push_str(HIDE);
        out.push_str(HIDE);
        out.push_str(HIDE);
    } else {
        out.push_str(HIDE);
        out.push_str(SHOW);
        out.push_str(HIDE);
        out.push_str(HIDE);
        out.push_str(HIDE);
    }
    out.push_str(&prompt_line(prompt, hint, ""));
    if let Some(note) = note {
        out.push_str(&note_line(note));
    }
    let _ = stderr.write_all(out.as_bytes());
    let _ = stderr.flush();

    // Read keys until Enter, tracking which answer is selected.
    let mut typed = String::new();
    let mut answer: Option<bool> = None;
    loop {
        let key = read_key()?;
        let mut buf = String::new();
        match key {
            Key::Char(c) => {
                typed.push(c);
                match c {
                    'y' | 'Y' => answer = Some(true),
                    'n' | 'N' => answer = Some(false),
                    _ => {}
                }
                buf.push_str(&render_cursor(lines, base_col + typed.chars().count()));
                buf.push_str(&prompt_line(prompt, hint, &typed));
                if let Some(note) = note {
                    buf.push_str(&note_line(note));
                }
            }
            Key::Enter => {
                let decided = answer.unwrap_or(default);
                buf.push_str(&render_cursor(lines, base_col + typed.chars().count()));
                buf.push_str(&final_line(prompt, decided));
                buf.push_str(HIDE);
                buf.push_str(SHOW);
                let _ = stderr.write_all(buf.as_bytes());
                let _ = stderr.flush();
                return Ok(decided);
            }
            Key::Other => {
                buf.push_str(&render_cursor(lines, base_col + typed.chars().count()));
