//! Terminal helpers: tty detection, terminal width and raw mode.

#[repr(C)]
#[derive(Default, Clone, Copy)]
struct Termios {
    c_iflag: u32,
    c_oflag: u32,
    c_cflag: u32,
    c_lflag: u32,
    c_line: u8,
    c_cc: [u8; 32],
    c_ispeed: u32,
    c_ospeed: u32,
}

extern "C" {
    fn isatty(fd: i32) -> i32;
    fn tcgetattr(fd: i32, termios: *mut Termios) -> i32;
    fn tcsetattr(fd: i32, optional_actions: i32, termios: *const Termios) -> i32;
    fn ioctl(fd: i32, request: u64, ...) -> i32;
}

const TCSANOW: i32 = 0;
const TIOCGWINSZ: u64 = 0x5413;

#[repr(C)]
#[derive(Default)]
struct Winsize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

/// Returns true when the given file descriptor is a terminal.
pub fn is_tty(fd: i32) -> bool {
    unsafe { isatty(fd) == 1 }
}

/// Returns the width of the terminal attached to one of the standard streams.
pub fn terminal_width() -> Option<u16> {
    for fd in [0, 1, 2] {
        let mut ws = Winsize::default();
        let r = unsafe { ioctl(fd, TIOCGWINSZ, &mut ws as *mut Winsize) };
        if r != -1 && ws.ws_col > 0 {
            return Some(ws.ws_col);
        }
    }
    None
}

thread_local! {
    static SAVED: std::cell::RefCell<Option<Termios>> = const { std::cell::RefCell::new(None) };
}

/// Enable or restore raw mode on stdin, returning the previous state.
pub fn raw_mode(enable: bool) -> bool {
    let was = SAVED.with(|c| c.borrow().is_some());
    if enable {
        let mut t = Termios::default();
        if unsafe { tcgetattr(0, &mut t as *mut Termios) } != 0 {
            return was;
        }
        let mut raw = t;
        raw.c_iflag &= !(0o1 | 0o2 | 0o20 | 0o40 | 0o400 | 0o2000 | 0o10000 | 0o20000);
        raw.c_oflag &= !0o1;
        raw.c_lflag &= !(0o10 | 0o2 | 0o40000 | 0o100000);
        raw.c_cc[6] = 1; // VMIN
        raw.c_cc[5] = 0; // VTIME
        if unsafe { tcsetattr(0, TCSANOW, &raw as *const Termios) } == 0 {
            SAVED.with(|c| *c.borrow_mut() = Some(t));
            return true;
        }
        was
    } else {
        let saved = SAVED.with(|c| c.borrow_mut().take());
        if let Some(t) = saved {
            unsafe { tcsetattr(0, TCSANOW, &t as *const Termios) };
        }
        false
    }
}
