fn no_break_before(c: char) -> bool {
    matches!(c, '.' | ':' | ',' | ';' | '\\'' | ')' | ']') || c.is_numeric()
}

/// Can a line break be inserted between `before` and `after`?
fn can_break(before: char, after: char) -> bool {
    if before.is_whitespace() {
