/// Greedy line wrapping: break at the last break opportunity that fits, falling
/// back to a hard break for unbreakable runs.
fn wrap_line(line: &str, width: usize) -> Vec<String> {
    let chars: Vec<char> = line.chars().collect();
    let n = chars.len();
    let mut out: Vec<String> = Vec::new();
    let mut pos = 0usize;
    loop {
        if pos >= n {
            break;
        }
        if n - pos <= width {
            let rest: String = chars[pos..].iter().collect();
            out.push(rest.trim_end().to_string());
            break;
        }
        let limit = pos + width;
        let mut best: Option<usize> = None;
        for i in (pos + 1)..=limit {
            let after = if i < n { chars[i] } else { ' ' };
            if can_break(chars[i - 1], after) {
                best = Some(i);
            }
        }
        match best {
            Some(p) => {
                let mut end = p;
                while end > pos && chars[end - 1].is_whitespace() {
                    end -= 1;
                }
                out.push(chars[pos..end].iter().collect());
                let mut next = p;
                while next < n && chars[next].is_whitespace() {
                    next += 1;
                }
                pos = next;
            }
            None => {
                out.push(chars[pos..limit].iter().collect());
                pos = limit;
            }
        }
    }
    out
}

